import{_ as d}from"./chunks/architecture.g4fIenb2.js";import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"架構地圖: 最終要組出什麼","description":"","frontmatter":{},"headers":[],"relativePath":"start/map.md","filePath":"start/map.md","lastUpdated":null}'),l={name:"start/map.md"};function n(h,t,i,s,c,b){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="架構地圖-最終要組出什麼" tabindex="-1">架構地圖: 最終要組出什麼 <a class="header-anchor" href="#架構地圖-最終要組出什麼" aria-label="Permalink to &quot;架構地圖: 最終要組出什麼&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: ● 必要, 所有讀者都讀</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 下圖是本手冊的終點, 也就是一套可以讓多人安全使用的地端 AI 系統. 手冊先在第一部說明每個方塊背後的原理, 再在第二部由下往上, 一次組裝一個模組. 多數讀者只需要組到其中一部分: 單人組到 M2, 小團隊組到 M6, 只有多人共用且有人每週維運時, 才組完整張圖.</p><p><img src="'+d+'" alt="地端 AI 部署架構: 雲端, 地端, 使用者端三區, 標示實體主機, VM, 設備與各連線協定"></p><p><strong>讀圖方式</strong>: 由下往上讀. 使用者只從內網連入反向代理, 經介面呼叫模型閘道, 再到推論伺服器. 珊瑚色元件接觸不可信內容, 紫色是可信控制區, 米色是基礎設施. 粗框是實體主機, 細框是 VM, 點線框是設備. 方塊上方是要安裝的軟體, 下方是角色.</p><h2 id="圖上每一塊由哪個模組組裝" tabindex="-1">圖上每一塊由哪個模組組裝 <a class="header-anchor" href="#圖上每一塊由哪個模組組裝" aria-label="Permalink to &quot;圖上每一塊由哪個模組組裝&quot;">​</a></h2><table tabindex="0"><thead><tr><th>圖上的方塊</th><th>組裝模組</th><th>先讀的底層知識</th><th>等級</th></tr></thead><tbody><tr><td>Proxmox VE, VM 分區, 備份伺服器</td><td><a href="/docs-handbook-poc/build/m0-foundation">M0 基礎環境</a></td><td>K6</td><td>●</td></tr><tr><td>vLLM (或 Ollama, llama.cpp)</td><td><a href="/docs-handbook-poc/build/m1-inference">M1 推論伺服器</a></td><td>K1, K2, K3</td><td>●</td></tr><tr><td>Open WebUI, Nginx 或 Caddy</td><td><a href="/docs-handbook-poc/build/m2-ui-proxy">M2 使用者介面與反向代理</a></td><td>K6</td><td>●</td></tr><tr><td>ModelScan, NFS 模型存放區, Hugging Face</td><td><a href="/docs-handbook-poc/build/m3-model-intake">M3 模型入庫與存放</a></td><td>K1, K4</td><td>○</td></tr><tr><td>Docling, Qdrant, 嵌入模型</td><td><a href="/docs-handbook-poc/build/m4-retrieval">M4 檢索 (RAG)</a></td><td>K1</td><td>○</td></tr><tr><td>LiteLLM, Keycloak, 雲端 API</td><td><a href="/docs-handbook-poc/build/m5-gateway-identity">M5 模型閘道與身分驗證</a></td><td>K6</td><td>○</td></tr><tr><td>Langfuse, OTel, Prometheus, 既有 SIEM</td><td><a href="/docs-handbook-poc/build/m6-observability">M6 可觀測, 稽核與評估</a></td><td>K5</td><td>○</td></tr><tr><td>MCP gateway, MCP 伺服器, Docker + gVisor</td><td><a href="/docs-handbook-poc/build/m7-tools-sandbox">M7 工具與沙箱</a></td><td>K5, K6</td><td>◇</td></tr><tr><td>LangGraph, OPA, 隔離模型</td><td><a href="/docs-handbook-poc/build/m8-agent-governance">M8 代理與治理</a></td><td>K5, K6</td><td>◇</td></tr><tr><td>n8n</td><td><a href="/docs-handbook-poc/build/m9-automation">M9 流程自動化</a></td><td>K5</td><td>○</td></tr></tbody></table><h2 id="三個里程碑" tabindex="-1">三個里程碑 <a class="header-anchor" href="#三個里程碑" aria-label="Permalink to &quot;三個里程碑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>完成的模組</th><th>適合</th><th>對應組合</th></tr></thead><tbody><tr><td>1. 能對話</td><td>M0 至 M2</td><td>單人, 單機</td><td>最小安全組合</td></tr><tr><td>2. 能查文件, 能多人用</td><td>再加 M3 至 M6</td><td>家庭或 2 至 10 人小團隊</td><td>標準組合</td></tr><tr><td>3. 能動手做事</td><td>再加 M7 至 M9</td><td>多人共用, 有人每週維運</td><td>進階組合 (整張圖)</td></tr></tbody></table><p>每個里程碑都是可以獨立使用的系統, 不必等全部組完. 各里程碑的檢核表見<a href="/docs-handbook-poc/build/overview">組裝總覽</a>. 用這些模組能解決哪些問題, 見<a href="/docs-handbook-poc/examples/">應用範例</a>.</p><h2 id="各層的必要性判斷" tabindex="-1">各層的必要性判斷 <a class="header-anchor" href="#各層的必要性判斷" aria-label="Permalink to &quot;各層的必要性判斷&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>分級</th><th>判斷依據</th></tr></thead><tbody><tr><td>推論層</td><td>必要</td><td>沒有推論伺服器就沒有服務</td></tr><tr><td>使用者介面層</td><td>必要</td><td>Open WebUI, LibreChat, AnythingLLM 擇一 (信心: 高)</td></tr><tr><td>身分與存取 / 網路層</td><td>必要</td><td>最小做法是只綁 localhost 或只開放內網, 不必上 SSO (信心: 高)</td></tr><tr><td>備份與更新層</td><td>必要</td><td>地端最常遺漏的必要層 (信心: 高)</td></tr><tr><td>機密管理層</td><td>必要, 最低限度</td><td><code>.env</code> 檔加權限 600 即可; Vault 或 OpenBao 對多數讀者過度 (信心: 中高, 屬推論)</td></tr><tr><td>檢索層 (RAG)</td><td>依情境</td><td>有「問自己文件」的需求才加 (信心: 高)</td></tr><tr><td>模型切換層</td><td>依情境</td><td>需要多個模型輪流佔用顯示記憶體時才加 llama-swap (信心: 中高)</td></tr><tr><td>閘道與路由層</td><td>依情境, 多人</td><td>符合 M5.1 節三項條件中的任兩項 (多人個別金鑰與配額, 混用雲端與地端, 多應用統一入口) 才加 (信心: 高)</td></tr><tr><td>可觀測性與評估層</td><td>評估必要, 追蹤依情境</td><td>一份回歸測試集是必要的; Langfuse 這類追蹤平台依情境 (信心: 中高)</td></tr><tr><td>編排與代理層</td><td>依情境</td><td>多數讀者用固定工作流程即可 (信心: 中高)</td></tr><tr><td>工具協定層 (MCP)</td><td>依情境, 進階</td><td>需要跨客戶端重用工具時才加 (信心: 中高)</td></tr><tr><td>沙箱層</td><td>依情境</td><td>只要讓模型執行程式碼就變成必要 (信心: 高)</td></tr><tr><td>護欄層</td><td>不建議單獨加</td><td>地端單人情境成本效益低, 權限設計比護欄模型更有效 (信心: 中)</td></tr><tr><td>Kubernetes</td><td>不建議</td><td>單機無法發揮排程與高可用的價值 (信心: 中高, 屬推論)</td></tr></tbody></table><p>資料來源: 研究 2《地端 AI 完整架構權衡研究》(2026-10-26), 分級與信心水準為該研究的整理判斷.</p><h2 id="「少而精」的判斷原則" tabindex="-1">「少而精」的判斷原則 <a class="header-anchor" href="#「少而精」的判斷原則" aria-label="Permalink to &quot;「少而精」的判斷原則&quot;">​</a></h2><p>2026 年的主要風險不在模型, 而在推論伺服器之上的中介層. 閘道 (LiteLLM), 低程式碼平台 (Langflow, n8n, Flowise) 與 MCP 實作都出現過已有實際利用紀錄的漏洞 (信心: 高, 依據為 CISA KEV, VulnCheck 與各廠商通報; 細節見 M5, M7, M9). 這類服務的共同點是同時保存金鑰, 又能執行程式碼, 因此一旦入侵成功, 影響範圍大於單一應用程式.</p><p>本手冊據此採用三條取捨原則:</p><ol><li><strong>能不加就不加</strong>: 每多一層, 就多一個要更新, 備份與監看公告的服務. 若無法每週檢查安全公告, 寧可少裝元件.</li><li><strong>先固定流程, 再考慮自主代理</strong>: 小模型單步工具呼叫約 78% 至 88%, 多輪任務只有約 30% 至 42% (BFCL V4, 見 K5).</li><li><strong>權限設計優先於偵測</strong>: 不給模型不需要的工具權限, 寫入與刪除需要人工確認, 比加護欄模型更有效.</li></ol><p>圖上的分區方式就是這三條原則的實作: 金鑰只放在閘道區, 接觸不可信內容的元件與有工具權限的元件分開, 所有工具呼叫都經過同一個工具閘道.</p>',18)])])}const M=a(l,[["render",n]]);export{u as __pageData,M as default};
